chain = ["주모델","예비1","예비2"]; down = {"주모델"}; cooldown_until = {}
def route(t):
    for m in chain:
        if cooldown_until.get(m,-1) > t: continue
        if m not in down: return m
        cooldown_until[m] = t + 30
for t in [0,5,31,40]:
    if t == 31: down.clear()
    print(f"t={t:>2}s → {route(t)}")
# t= 0s → 예비1
# t= 5s → 예비1
# t=31s → 주모델
# t=40s → 주모델
